Tool response:
Tool: search_recipes
Description: Search for recipes matching style and quality criteria.
Parameters:
    {
      "type": "object",
      "properties": {
        "style": {
          "type": "string",
          "description": "Recipe style to filter by",
          "title": "Style"
        },
        "min_abv": {
          "type": "number",
          "description": "Minimum ABV percentage",
          "title": "Min Abv"
        },
        "max_abv": {
          "type": "number",
          "description": "Maximum ABV percentage",
          "title": "Max Abv"
        },
        "max_ibu": {
          "type": "integer",
          "description": "Maximum IBU rating",
          "title": "Max Ibu"
        }
      },
      "required": [
        "style",
        "min_abv",
        "max_abv",
        "max_ibu"
      ]
    }

Tool response:
Tool: clone_recipe
Description: Clone a recipe to the current user's collection.
Parameters:
    {
      "type": "object",
      "properties": {
        "recipe_id": {
          "type": "integer",
          "title": "Recipe Id",
          "description": ""
        }
      },
      "required": [
        "recipe_id"
      ]
    }
